mapper.select:
SELECT decision_id, workspace_id, requester_issuer, requester_type, requester_id, permission_code, resource_type, resource_id, outcome, reason_code, policy_version, request_id, trace_id, evaluated_at FROM ( SELECT decision_id, workspace_id, requester_issuer, requester_type, requester_id, permission_code, resource_type, resource_id, outcome, reason_code, policy_version, request_id, trace_id, evaluated_at FROM ainer_authorization_decision_audit UNION ALL SELECT decision_id, workspace_id, requester_issuer, requester_type, requester_id, permission_code, resource_type, resource_id, outcome, reason_code, policy_version, request_id, trace_id, evaluated_at FROM ainer_authorization_decision_audit_archive ) audit WHERE workspace_id = #{workspaceId}
AND (evaluated_at, decision_id) < (#{afterEvaluatedAt}, #{afterDecisionId})
ORDER BY evaluated_at DESC, decision_id DESC LIMIT #{limit}
